counterexample:
INSERT INTO table1 (c1, c2) VALUES ('a','a');
INSERT INTO table1 (c1, c2) VALUES ('a','b');
INSERT INTO table1 (c1, c2) VALUES ('b','b');

-- For the purpose of this counterexample, assume that the storage engine distinguishes two day‐1 login events for the same user on the same calendar day (for example by including a hidden time component) so that the primary key (c4, c2) is not violated in practice.

-- User 1: installs on 2020-01-01 and has two distinct logins on 2020-01-02
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-01', 100, 10);
-- The two following inserts represent two separate login events on the same calendar day (2020-01-02)
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-02', 101, 20);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-02', 102, 30);

-- User 2 (control): installs on 2020-01-01 and logs in once on 2020-01-02
INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2020-01-01', 200, 40);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2020-01-02', 201, 50);

-- When grouping by install date (2020-01-01):
-- Q1 will compute INSTALLS = 2 and its numerator as  (2 [from user 1’s two day1 logins] + 1 [from user 2]) = 3, so DAY1_RETENTION = 3/2 = 1.50 (rounded to 1.50).
-- Q2 will compute INSTALLS = 2 and COUNT(DISTINCT DAY_ONE_ID) = 2 (one per user) so DAY1_RETENTION = 2/2 = 1.00.

-- Thus, the two queries produce different results for 2020-01-01.

