-- For the sake of this counterexample, assume that table1’s primary key is modified so that duplicates on (c4,c2) are allowed (for example, by making the primary key (c4,c3) instead).

-- Insert two rows for c4=1 that share the same c2 (the minimum in that group) but have different c1 values
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-01', 100, 1);
