-- The following INSERT statements assume that duplicate rows (with the same (c4, c2)) are allowed (or that the reporting layer may receive duplicates) even though the schema’s primary key prevents them in the base table.  
-- They illustrate the semantic difference between Q1 and Q2.

-- Group 1 (c4 = 1): minimum event is 2020-01-01 and two records occur for 2020-01-02
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-01', 10, 100);
