counterexample:
/* First, alter table1 to add a column named c4. This does not violate any constraints because we are only extending the table. */
ALTER TABLE table1 ADD COLUMN c4 INT;

/* Insert data into table1. Notice that we are now providing a value for the new c4 column which is NOT the same as the c4 column in table2. */
INSERT INTO table1 (c1, c3, c2, c4) VALUES (1, 'John', 20, 100);
INSERT INTO table1 (c1, c3, c2, c4) VALUES (2, 'Jane', 40, 200);

/* Insert data into table2. Its primary key is (c4, c1) so we use different c4 values here – these represent a grouping key that Q1 will use. */
INSERT INTO table2 (c4, c1) VALUES (300, 1);
INSERT INTO table2 (c4, c1) VALUES (300, 2);
INSERT INTO table2 (c4, c1) VALUES (400, 1);
INSERT INTO table2 (c4, c1) VALUES (400, 2);

/*
Explanation of the results:
In Q1, the query uses A.c4 (i.e. table2.c4) so the grouping is by 300 and 400. The joined rows are:
  For table2.c4 = 300: joining rows for c1=1 and c1=2; the average is AVG(20,40)=30.00.
  For table2.c4 = 400: again joining rows for c1=1 and c1=2; the average is 30.00.

In Q2, if the SQL engine resolves the unqualified c4 to mean table1.c4, then the grouping keys become the values 100 and 200 from table1. But note that the join is still performed on c1; however, because the GROUP BY expression comes from table1 (due to the name collision) the two join rows (for c1=1 and c1=2) now fall into two separate groups: one with table1.c4=100 and one with table1.c4=200. The averages computed from each group then are simply 20.00 and 40.00 respectively.
Thus the two queries yield different outputs.
*/

-- Assume we are in a test environment where we can disable or ignore the primary key constraint on table1 so as to simulate duplicate rows. 

-- Insert duplicate rows into table1 for c3 = 1
INSERT INTO table1 (c3, c4, c8) VALUES (1, 'Alice', 100);
INSERT INTO table1 (c3, c4, c8) VALUES (1, 'Alice_Duplicate', 100);

-- Insert a normal row for another key
INSERT INTO table1 (c3, c4, c8) VALUES (2, 'Bob', 200);

-- For c3 = 1, all table2 rows have dates within the range
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 10, 101, '2019-01-15', 0, 0);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 20, 102, '2019-03-15', 0, 0);

-- For c3 = 2, one row is within the range and one is out of range
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 30, 201, '2019-01-15', 0, 0);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 40, 202, '2019-04-01', 0, 0);

-- Expected behavior:
-- Q1: Its subquery on table2 groups by c3 and yields only c3 = 1 (since for c3=2 the date range condition fails). Then joining to table1 returns both rows for c3 = 1. 
-- Q2: The join (which multiplies table1 rows) yields two joined rows for c3 = 1; then grouping by S.c3 (and depending how the non-grouped column P.c4 is chosen) will yield a single row (or if DISTINCT is applied before grouping, two different versions) for c3 = 1. 
-- Thus, in an engine that does not enforce functional dependency on the grouped columns, the two queries will produce different results regarding the chosen value of c4 for c3 = 1.

INSERT INTO table1 (c3, c4, c8) VALUES (1, 'S8', 10);
INSERT INTO table1 (c3, c4, c8) VALUES (2, 'S8', 20);
INSERT INTO table1 (c3, c4, c8) VALUES (3, 'IPHONE', 30);

INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 1, 100, '2023-01-01', 1, 1);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 1, 200, '2023-01-01', 1, 1);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (3, 1, 100, '2023-01-01', 1, 1);

