/* Prepare table2 data */
-- Row A: joins with table1 row 1 (S8) and has c1 = 100
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 0, 100, '2020-01-01', 0, 0);

-- Row B: joins with table1 row 2 (IPHONE) but gives a duplicate c1 = 100
-- To force the discrepancy note that here we purposely insert a NULL in one column
-- so that in one subquery the candidate is hidden by a NULL in the exclusion set.
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 0, NULL, '2020-01-02', 0, 0);

-- Row C: another row joining to an S8 record with a different c1, say 200 (control row)
INSERT INTO table1 (c3, c4, c8) VALUES (4, 'S8', 40);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (4, 0, 200, '2020-01-03', 0, 0);

/* With this data:
   • Q1 does an inner join for S8 rows and finds candidate 100 (from table1.c3 = 1) and 200 (from c3 = 4).
   • Its IPHONE subquery (which is an inner join) finds only the row from c3 = 2; however, since that row’s c1 is NULL, the set of values is {NULL}.
     Then the condition "value NOT IN (NULL)" evaluates to UNKNOWN for any non‐NULL value. 
   • In many SQL engines Q1 will then return no rows.
   • On the other hand Q2’s subquery builds the exclusion set as well–but the way the left join and group by work may allow the S8 candidate from c3 = 1 (with 100) to slip through if the NULL is handled differently.
   (Depending on the SQL dialect, one query will return phone id 100 while the other will not, thus demonstrating they are not semantically equivalent.)
*/

/*
Assuming the possibility of duplicate event‐rows for the same day (even though table1’s PK ideally should prevent it), the following INSERT statements create a counterexample.

For group 1 (c4=1):
  • The minimum date is 2020-01-01.
  • There are two rows for 2020-01-02 (i.e. 1 day later).
For group 2 (c4=2):
  • The minimum date is 2020-01-01.
  • There is one row for 2020-01-02.

Q1 will compute the numerator as 1 + 1 = 2 (one match per group), with denominator = 2, so FRACTION = 1.00.
Q2 will compute the numerator as 2 (from group 1) + 1 (from group 2) = 3, with the denominator still 2 (distinct groups), so FRACTION = 1.50.
This illustrates that Q1 and Q2 can return different results.

Note: Under the given schema the PK (c4,c2) prevents true duplicates. However, this counterexample simulates the effect of duplicate "day after" events that might occur in practice (for example, if the constraint were missing or if the data‐loading process introduced anomalies).
*/

INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-01', 10, 100);
-- Simulate two records on 2020-01-02 for c4=1 (data anomaly duplicate)
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-02', 20, 200);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-02', 21, 201);

INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2020-01-01', 30, 300);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2020-01-02', 40, 400);

