/*
Assume that although the schema declares c2 as a DATE and the primary key is (c4,c2), the system in practice records events with an underlying time‐component so that two events on the same calendar day can be distinguished. (Many databases use DATE types that hide the time portion, but if the underlying storage allows two distinct events on the same day—such as by inserting the same date literal but with different other column values—the PK may be defined on a converted value or the data comes from a source where duplicates on a day are possible.)
*/

-- User 101 installs on 2023-01-01 and then has two separate login events on 2023-01-02 (the retention day).
INSERT INTO table1 (c4, c2, c1, c3) VALUES
  (101, '2023-01-01', 1, 10);

-- Two login events on the day following installation. In many implementations the DATE value is stored without a time part but the source data may have distinct timestamps; here we simulate that by inserting two rows having the same c2 value (and assuming the system distinguishes them by extra time‐info not in the key).
INSERT INTO table1 (c4, c2, c1, c3) VALUES
  (101, '2023-01-02', 2, 20);
INSERT INTO table1 (c4, c2, c1, c3) VALUES
  (101, '2023-01-02', 3, 30);

-- User 102 installs on 2023-01-01 and logs in only once on 2023-01-02 (the expected behavior).
INSERT INTO table1 (c4, c2, c1, c3) VALUES
  (102, '2023-01-01', 4, 40);
INSERT INTO table1 (c4, c2, c1, c3) VALUES
  (102, '2023-01-02', 5, 50);

/*
Expected result when grouping by install date (displayed as INSTALL_DT):
  For INSTALL_DT = '2023-01-01':
    • Q1 will compute INSTALLS = 2 (users 101 and 102) but DAY1_RETENTION will be computed as (for user 101: 2 events, for user 102: 1 event) so the sum is 3; then retention = ROUND(3/2,2) = 1.50.
    • Q2 will compute INSTALLS = 2 and will count a retention event per user (even if user 101 has two events, it is expected to be counted only once in a pure retention metric) so DAY1_RETENTION = ROUND(2/2,2) = 1.00.
Thus, the two queries return different results for 2023-01-01.
*/

INSERT INTO table1 (c3, c4, c5, c1, c2) VALUES (1, 1, 0.005, 1, 2);
INSERT INTO table1 (c3, c4, c5, c1, c2) VALUES (2, 1, 10, 2, 3);
