INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 10, 1, '2020-01-01', 100, 1000);

-- For the IPHONE row, table2 has two rows: one with c1 = 1 and one with a NULL in c1
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 20, 1, '2020-01-02', 200, 2000);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 30, NULL, '2020-01-03', 300, 3000);

