INSERT INTO table1 (c3, c4, c8) VALUES (2, 'IPHONE', 200);
INSERT INTO table1 (c3, c4, c8) VALUES (3, 'S8', 300);

-- For candidate 1 we insert two rows in table2: one that joins to a S8 row and one that joins to an IPHONE row
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 10, 1, '2021-01-01', 0, 0);  -- joins to table1.c3=1 (S8)
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 20, 1, '2021-01-02', 0, 0);  -- joins to table1.c3=2 (IPHONE)

-- For candidate 2 only a S8 row appears
