-- Insert data into table1. Note that in addition to c2 and c6 (the intended columns), we also fill in the extra columns c3_ext and c4_ext which the developer might have intended to use but might be confused with table2's c3 and c4
INSERT INTO table1 (c1, c5, c2, c6, c3_ext, c4_ext) VALUES (10, 1, 'T1_x', 'T1_y', 'T1_extra1', 'T1_extra2');

