schema:
CREATE TABLE table1 (
    c2 INT PRIMARY KEY,
    c1 BOOL
);

counterexample:
INSERT INTO table1 (c2, c1) VALUES (1, 1);
INSERT INTO table1 (c2, c1) VALUES (2, 1);
INSERT INTO table1 (c2, c1) VALUES (3, 1);
INSERT INTO table1 (c2, c1) VALUES (4, 1);  

-- Explanation:
-- For c2=1: Q1 checks for a row with c2=0 (none) or c2=2 (found with c1=1) so 1 is returned.
-- For c2=2: It finds neighbor 1 (c1=1) and/or 3 (c1=1) so 2 is returned.
-- For c2=3: It finds neighbor 2 (c1=1) and qualifies, so 3 is returned.
-- For c2=4: Q1 checks for c2=3 (exists) and c2=5 (missing). Even though there is a row with c2=3 the test in Q1 will work (since 3’s c1=1) so 4 is returned by Q1.

-- However, if you were to remove the row with c2=3, then the row with c2=4 would have no adjacent row (since neither 3 nor 5 exist) and Q1 would not return it. In contrast, Q2 always requires an inner join partner. Also, note that Q2 always returns the answer sorted by c2 while Q1 does not. 

-- (You can experiment by removing or adding rows so that a row that qualifies in Q1 via one subquery might not find a join partner in Q2.)

INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2023-01-02', 10, 100);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, NULL, 20, 200);

-- Also add an additional group with only non-null c2 values to show that when no NULL is present both queries return the same row:
INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2023-01-01', 30, 300);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2023-01-02', 40, 400);

-- Note: Although the schema declares a primary key on (c4, c2), many real login tables allow multiple logins per day (often by storing DATETIME values instead of DATE). For this counterexample we assume that duplicates on the same calendar day are possible, e.g. because c2 actually stores a timestamp.

INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2021-01-01', 10, 100);
