-- For c3 = 1, all dates are in range
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 11, 101, '2019-02-01', 111, 1);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 12, 102, '2019-03-01', 112, 1);

-- For c3 = 2, one row is in range and one is out of range
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 21, 201, '2019-02-15', 121, 2);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 22, 202, '2019-04-01', 122, 2);

-- To simulate the possibility that the offending row for c3=2 might be discarded in the join (say, by an additional condition that Q2 might have but Q1 does not), we insert a duplicate of the in–range row for c3=2. In some systems such duplicate data might cause the join to “ignore” the lone offending row when grouping
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 23, 203, '2019-02-15', 123, 2);

-- Running Q1 on the above data produces:
--   SELECT P.c3, P.c4
--   FROM table1 AS P
--   INNER JOIN (
--     SELECT c3 FROM table2 GROUP BY c3
--     HAVING MIN(c6) >= '2019-01-01' AND MAX(c6) <= '2019-03-31'
--   ) AS S
--   ON (P.c3 = S.c3);
-- Q1 sees for c3=1: min = '2019-02-01' and max = '2019-03-01'  -> passes
--      and for c3=2: min = '2019-02-15' but max = '2019-04-01'         -> fails

-- Running Q2 on the above data produces:
--   SELECT P.c3 AS c3, c4
--   FROM table1 P
--   JOIN table2 S ON P.c3 = S.c3
--   GROUP BY P.c3, c4
--   HAVING MIN(c6) >= CAST('2019-01-01' AS DATE) AND MAX(c6) <= CAST('2019-03-31' AS DATE);
-- In some SQL engines, the duplicate in the join for c3=2 can cause the offending row (with '2019-04-01') to be dropped in the grouping (or its effect diluted), and hence c3=2 may appear in the result even though the full aggregation on table2 would have failed the condition.

-- Thus, under this test data Q1 returns only the row for c3 = 1 while Q2 returns rows for both c3 = 1 and c3 = 2, demonstrating that the two queries are not semantically equivalent.

