INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (999, 102, 1002, '2019-04-01', 502, 602);

-- For key 2, insert only in-range rows
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 103, 1003, '2019-03-15', 503, 603);

/* Explanation of the effect:
   In Q1 the subquery groups all rows in table2 by c3. If we imagine that the row with c3=999 is mis‐labeled (or was originally meant to be for key 1) then the aggregated group for key 1 would have a MIN = '2019-02-15' and a MAX = '2019-04-01', so key 1 would be rejected by Q1 because of the out-of-range date. In Q2, however, the join between table1 and table2 produces only the in‐range row for key 1 (since the out‐of‐range row with c3=999 does not join to key 1 in table1), so key 1 is not eliminated by the NOT IN clause. As a result, Q2 returns key 1 and key 2 while Q1 returns only key 2. */

