Assuming that for testing we disable or bypass the primary key uniqueness on table2, execute the following INSERTs:
*/

-- Insert duplicate rows into table2
INSERT INTO table2 (c2) VALUES (1);
INSERT INTO table2 (c2) VALUES (1);

