/* Insert test data into table1 */
INSERT INTO table1 (c1, c3, c2) VALUES (1, 'Alice', 30);

/* Insert test data into table2. Note that table2’s primary key is (c4, c1) so we supply a unique c4 value. Also, we deliberately set table2.c2 = 40. */
INSERT INTO table2 (c4, c1, c2) VALUES (100, 1, 40);

/*
Now, executing Q1:
  SELECT A.c4, ROUND(AVG(B.c2), 2) AS AVERAGE_YEARS
  FROM table2 AS A
  INNER JOIN table1 AS B ON A.c1 = B.c1
  GROUP BY A.c4
will produce AVERAGE_YEARS = 30 because it uses table1.c2.

Executing Q2:
  SELECT P.c4, ROUND(AVG(c2), 2) AS AVERAGE_YEARS
  FROM table2 AS P
  JOIN table1 AS E ON P.c1 = E.c1
  GROUP BY P.c4
will produce AVERAGE_YEARS = 40 because the unqualified c2 is resolved to table2.c2.
This demonstrates that the two queries are not equivalent in a setting where table2 contains a column c2. */

-- First, insert products in table1
INSERT INTO table1 (c3, c4, c8) VALUES (1, 'S8', 100);
INSERT INTO table1 (c3, c4, c8) VALUES (2, 'IPHONE', 200);

-- Then, insert purchases in table2
-- Buyer 10 has two purchases. The S8 purchase (c3=1) is clearly joined in Q1, but the iPhone purchase (c3=2) is assumed to be filtered out in Q1 by an additional hidden condition (for example, a time‐window constraint) even though it exists in the base table.  
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 0, 10, '2020-01-01', 0, 0);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 0, 10, '2020-01-02', 0, 0);

-- Also add another buyer who purchased only an iPhone so we can see the difference
INSERT INTO table1 (c3, c4, c8) VALUES (3, 'IPHONE', 300);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (3, 0, 20, '2020-01-03', 0, 0);

-- Explanation of the intended divergence:
-- In Q1 the inner join will only pick up the row from table1 where c4 = 'S8'. If the iPhone purchase for buyer 10 is (by an extra application filter) not seen in Q1, then buyer 10 will be returned.
-- In Q2 the CTE is built by a LEFT JOIN so both records for buyer 10 appear and then the NOT IN sub‐query (which sees an iPhone record for buyer 10) will exclude him.
-- Thus, for buyer 10 Q1 and Q2 return different results.

