INSERT INTO table1 (c3, c1, c2) VALUES (3, 1, 2);
INSERT INTO table1 (c3, c1, c2) VALUES (4, 1, 2);
INSERT INTO table1 (c3, c1, c2) VALUES (5, 1, 2);

-- a group that should not appear since it has only two rows (and thus does not meet the count >= 3 condition)
INSERT INTO table1 (c3, c1, c2) VALUES (6, 3, 4);

-- Assume that we can temporarily disable the primary key constraint (or that duplicates occur due to a bug) so that a device may have two records for the same date.  

-- Device 1 installs on 2023-01-01 and then has two records on 2023-01-02 (its Day-1) 
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2023-01-01', 10, 100);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2023-01-02', 20, 200);
-- A duplicate Day-1 record for the same device (e.g. from a duplicate event) 
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2023-01-02', 30, 300);

-- Device 2 installs on 2023-01-01 but does not return on Day-1
INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2023-01-01', 11, 101);

-- Explanation of results:
-- For install_dt = '2023-01-01':
-- Q1’s inner join (without DISTINCT in the CASE sum) will see for device 1 two rows that satisfy (FIRST_LOGIN + 1 = '2023-01-02') and for device 2 zero. Its numerator becomes 2, while the denominator (COUNT DISTINCT devices) is 2, yielding a DAY1_RETENTION of 1.00.
-- Q2’s LEFT JOIN will match at most one record per device (using COUNT(DISTINCT A.c4)) so that for device 1 only one Day‑1 return is counted and the retention becomes 0.50.

-- Thus, the two queries produce different results.

