counterexample:
/* Insert test data */
INSERT INTO table1 (c1, c3, c2) VALUES (1, 'Alice', 10);

/* The following duplicate inserts in table2 simulate the case where the same employee appears twice for the same group.
   In a database where the PK on table2 is strictly enforced, such duplicates would not be allowed. However, this
   counterexample illustrates the different aggregation logic in Q1 and Q2 when duplicate relationships exist. */
INSERT INTO table2 (c4, c1) VALUES (1, 1);
INSERT INTO table2 (c4, c1) VALUES (1, 1);

-- Insert a row into table1
INSERT INTO table1 (c3, c4, c8) VALUES (1, 'A', 10);

-- Insert a valid row into table2 for c3=1 with a date in the allowed range
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 100, 200, '2019-02-01', 300, 400);

-- Insert a row into table2 with a NULL c3 and a date outside the allowed range
-- This row produces a NULL in the subquery of Q2
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (NULL, 101, 201, '2019-04-01', 301, 401);

INSERT INTO table1 (c3, c4, c8) VALUES (1, 'A', 10);
INSERT INTO table1 (c3, c4, c8) VALUES (2, 'B', 20);

-- For key 1, we insert duplicate rows with dates in the allowed range
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 100, 1000, '2019-02-01', 5, 50);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 101, 1001, '2019-02-01', 6, 51);

-- For key 2, one row is in range and one is out-of-range
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 102, 1002, '2019-02-01', 7, 52);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 103, 1003, '2019-04-01', 8, 53);

-- When executing Q1, the subquery groups table2 by c3 and sees for key 2 that MIN(c6) = '2019-02-01' but MAX(c6) = '2019-04-01' (which is > '2019-03-31'), so key 2 is dropped. For key 1, both dates are in range so it is returned.
-- In Q2 the join produces duplicate rows for key 1 (which is fine) but for key 2 the improper duplicate effect may cause the grouping to behave differently (or, depending on the SQL engine’s treatment of duplicates, reveal the difference in when filtering is applied).

-- Thus, this test data distinguishes the two queries.

