/*
  First, we simulate an extension of table2 by adding a column c2. (This extra column does not affect the primary key and does not violate any constraint.)
*/
ALTER TABLE table2 ADD COLUMN c2 INT;

-- Insert data into table1
INSERT INTO table1 (c1, c3, c2) VALUES (1, 'Alice', 10);
INSERT INTO table1 (c1, c3, c2) VALUES (2, 'Bob', 20);

-- Insert data into table2, with explicit values for the new c2 column
INSERT INTO table2 (c4, c1, c2) VALUES (100, 1, 5);
INSERT INTO table2 (c4, c1, c2) VALUES (100, 2, 5);

/*
  Now consider the two queries:

  Q1:
  SELECT A.c4, ROUND(AVG(B.c2), 2) AS AVERAGE_YEARS
  FROM table2 AS A
    INNER JOIN table1 AS B ON A.c1 = B.c1
  GROUP BY A.c4;
  --> This query computes AVG over table1.c2 so it gives: (10+20)/2 = 15.00

  Q2:
  SELECT P.c4, ROUND(AVG(c2), 2) AS AVERAGE_YEARS
  FROM table2 AS P
    INNER JOIN table1 AS E ON P.c1 = E.c1
  GROUP BY P.c4;
  --> In a SQL dialect where the unqualified c2 resolves to table2.c2 (because table2 now has a column c2), the result is: (5+5)/2 = 5.00
*/

