/*
Assume that for demonstration purposes (for example if c2 were defined as a datetime rather than a DATE type) the primary‐key constraint is not violated when multiple logins occur on the same calendar day. (In some systems you may allow multiple logins per day if the time part is stored.)
*/

INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2021-01-01', 10, 100);
