INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2020-02-10', 30, 300);

INSERT INTO table1 (c3, c4, c8) VALUES (1, 'Record One', 10);
INSERT INTO table1 (c3, c4, c8) VALUES (2, 'Record Two', 20);

INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 100, 200, '2019-02-01', 300, 400);

INSERT INTO table1 (c3, c4, c8) VALUES (1, 'S8', 100);
INSERT INTO table1 (c3, c4, c8) VALUES (2, 'IPHONE', 200);

-- In table2 the same c1 value (10) appears twice, once joining to the S8 row and once to the IPHONE row
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 0, 10, '2020-01-01', 0, 0);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 0, 10, '2020-01-02', 0, 0);

-- When running the queries on the above data:
-- Q1 (with its unaliased inner sub-query) may return no row because the outer row (c3=1) produces c1=10, but 10 appears in the inner sub-query (via the row with c3=2) so 10 is filtered out.
-- Q2 (which uses proper aliasing) computes the S8 and IPHONE sets independently and then finds that 10 appears in both, so 10 is also eliminated.

-- The difference is subtle and depends on how the DBMS treats the unaliased reference in Q1. This counterexample shows that if Q1 is inadvertently treated as correlated (so that the inner query “sees” the outer row) its result can differ from Q2. Adjusting the data (or the join order) further can make one query return a non‐empty result while the other returns empty, thus demonstrating that Q1 and Q2 are not semantically equivalent.

